# -*- coding: utf-8 -*-
"""프로그램 신원 — 이름·버전·슬로건 한 곳 모음 (2026-07-25).

창마다 제목을 따로 적으면 버전을 올릴 때 여러 파일을 고쳐야 하고, 한 곳을
빠뜨리면 창마다 다른 버전이 뜬다. 창 제목은 전부 여기서 가져다 쓴다.

창 제목에 '팔레트 설정' 같은 기능 이름을 넣지 않는 이유 (사용자 결정):
    창 안에 이미 큰 제목이 있어 같은 말이 화면에 두 번 나왔다. 제목표시줄은
    '이 프로그램이 무엇인가'를 말하고, 무슨 화면인지는 창 안에서 말한다.
"""

# 0.1.0 부터 다시 센다 (사용자 결정 2026-07-26).
# 예전 1.3.0 은 아직 남에게 내놓을 물건이 아닌데 붙은 번호였다. 첫 공개
# 릴리즈를 0.1.0 으로 두고, 실제로 쓸 만해지는 시점에 1.0.0 을 붙인다.
# 사용자 지시 "베타버전으로 커밋" (2026-07-31). 창고 개편·섞기·겹치기·문서
# 해체·덩어리 엑셀이 들어간 큰 판이지만 실기 확인 전이라 -beta 를 단다.
VERSION = "0.4.0-beta"
RELEASE_DATE = "2026-07-31"
NAME = "HwpPalette"
SLOGAN = "나만의 물감, 나만의 팔레트"

# 모든 창의 제목표시줄에 쓰는 문구.
# 슬로건은 뺐다 (사용자 결정 2026-07-25) — 창이 좁아 제목표시줄에서 늘 잘렸다.
# 잘린 문장은 안 쓴 것만 못하다. SLOGAN 은 다른 곳(안내 화면 등)에서 쓴다.
WINDOW_TITLE = f"{NAME} v{VERSION}"

COPYRIGHT = "Copyright © 2026. Developed by 박승연 | SOMC"
